import React, { useEffect, useState } from "react";
import { BrowserRouter as Router, Routes, Route, useLocation } from "react-router-dom";
import UserLayout from "../UserLayout"; // Import the UserLayout
import VetLayout from "./components/VetLayout"; // Import the VetLayout
import JsonData from "./data/data.json";
import LandingPage from "./components/landing"; 
import Login from "./components/login";
import Register from "./components/register";
import Findavet from "./components/findavet";
import Shops from "./components/shops";
import PetShop from "./components/petshop";
import ShopProfile from "./components/shopprofile";
import OtpPage from "./components/otppage";
import VetDashboard from "./components/VetDashboard";
import VetAppointments from "./components/VetAppointments";
import VetHistory from "./components/VetHistory";
import VetLogin from "./components/VetLogin";
import ProfilePage from "./components/profile";

const App = () => {
  const [landingPageData, setLandingPageData] = useState({});
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const location = useLocation(); // Get the current location

  useEffect(() => {
    setLandingPageData(JsonData);
    // Check if the token exists in localStorage on app load
    const token = localStorage.getItem("token");
    setIsLoggedIn(!!token); // Update logged in state based on token presence
  }, []);

  return (
    <Routes>
      {/* User Routes */}
      <Route path="/" element={<User Layout landingPageData={landingPageData} isLoggedIn={isLoggedIn} setIsLoggedIn={setIsLoggedIn} />}>
        <Route index element={<LandingPage />} />
        <Route path="/home" element={<LandingPage />} />
        <Route path="/login" element={<Login setIsLoggedIn={setIsLoggedIn} />} />
        <Route path="/register" element={<Register />} />
        <Route path="/findavet" element={<Findavet />} />
        <Route path="/shops" element={<Shops />} />
        <Route path="/petshop/:clinicId" element={<PetShop />} />
        <Route path="/shopprofile/:clinicId" element={<ShopProfile />} />
        <Route path="/otp" element={<OtpPage />} />
        <Route path="/profile" element={<ProfilePage />} />
      </Route>

      {/* Clinic Routes */}
      <Route path="/clinic/*" element={<VetLayout />}>
        <Route path="dashboard" element={<VetDashboard />} />
        <Route path="appointments" element={<VetAppointments />} />
        <Route path="history" element={<VetHistory />} />
      </Route>

      <Route path="/AdminLogin" element={<VetLogin />} />
    </Routes>
  );
};

// Wrap App in Router
const AppWrapper = () => (
  <Router>
    <App />
  </Router>
);

export default AppWrapper;
